import {readFile,writeFile} from 'node:fs/promises'
import {createServer} from 'node:http'
import assert from 'node:assert/strict'
import {randomUUID} from 'node:crypto'
import express from '/workspace/eduK12-new-version/server-version/backend/node_modules/express/index.js'
import {prisma as db} from '/workspace/eduK12-new-version/server-version/backend/src/config/database'
import routes from '/workspace/eduK12-new-version/server-version/backend/src/modules/questionnaire-product/routes'
import {errorHandler} from '/workspace/eduK12-new-version/server-version/backend/src/middleware/errorHandler'
import {generateToken} from '/workspace/eduK12-new-version/server-version/backend/src/utils/jwt'
import {closeQueues} from '/workspace/eduK12-new-version/server-version/backend/src/config/queue'
async function main(){
 const u=new URL(process.env.DATABASE_URL!);assert.equal(u.hostname,'127.0.0.1');assert.equal(u.port,'55439');assert.equal(u.pathname,'/precise_dual_report_test_20261030_v2');assert.equal(u.username,'precise_task1_runtime')
 const state=JSON.parse(await readFile('/workspace/materials-load-20261029/dual-report-v2-private.json','utf8'))
 const app=express();app.use(express.json());app.use('/api/questionnaire-products',routes);app.use(errorHandler);const server=createServer(app);await new Promise<void>(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+(server.address() as any).port
 const count=async()=>({uses:await db.materialGrant.count(),events:await db.assessmentManagementEvent.count(),attempts:await db.compositeAssessmentAttempt.count()});const before=await count(),requests:any[]=[]
 try{
  for(const name of ['standardTeacher','funTeacher']){
   const user=await db.user.findUniqueOrThrow({where:{id:state[name+'Id']}}),token=generateToken({userId:user.id,username:user.username,role:user.role,accountDomain:'TRAINING',tokenVersion:user.tokenVersion})
   const get=async(path:string,status=200)=>{const response=await fetch(base+path,{headers:{Cookie:'ptool_session='+token,Origin:'http://localhost:5173'}}),body=await response.json() as any;requests.push({actor:name,path,status:response.status});assert.equal(response.status,status,body.message);return body.data}
   const page=await get('/api/questionnaire-products/standard-combination-choices');assert.equal(page.list.length,1);assert.equal(page.list[0].available,true);assert.equal(page.nextCursor,null)
   const c=page.list[0];const query=new URLSearchParams({afterToolKey:c.toolKey,afterReleaseId:c.combination.releaseId,afterUseId:c.useGrantId});assert.deepEqual(await get('/api/questionnaire-products/standard-combination-choices?'+query),{list:[],nextCursor:null})
   await get('/api/questionnaire-products/standard-combination-choices?afterToolKey=partial',400)
  }
  const denied=await fetch(base+'/api/questionnaire-products/standard-combination-choices');assert.equal(denied.status,401);requests.push({actor:'anonymous',status:denied.status})
  assert.deepEqual(await count(),before);await writeFile('/workspace/training-choice-pagination-20261030/evidence/picker-http-readback.json',JSON.stringify({passed:true,database:u.pathname.slice(1),restrictedRole:u.username,syntheticActorsOnly:true,requests,businessCountsUnchanged:before,scope:'Actual protected GET and PostgreSQL page/probe SQL only. Existing synthetic two-R grants reused, no seed/grant/FINAL writes.'},null,2)+'\n');console.log('PASS protected pagination GET, real PG lateral query, partial-cursor and anonymous rejection; business counts unchanged')
 }finally{server.closeAllConnections();await new Promise<void>(r=>server.close(()=>r()));await closeQueues(true);await db.$disconnect()}
}
main().catch(e=>{console.error(e);process.exitCode=1})
